(function(){
  'use strict';
  const G=window.StudioGame;
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const disabled=ok=>ok?'':' disabled';
  function portrait(m){const ai=m.id==='ace',look=m.look||0,color=m.color||'#d8b879';return `<svg class="person-portrait" viewBox="0 0 80 86" role="img" aria-label="${esc(m.name)}的头像"><rect width="80" height="86" rx="16" fill="${color}" opacity=".12"/><circle cx="40" cy="33" r="24" fill="${color}" opacity=".12"/>${ai?`<path d="M15 86V72q1-18 25-18t25 18v14" fill="#304a47"/><path d="M18 32Q13 8 40 7t23 28l4 42-13-5-2-27H28l-3 29-13 3Z" fill="#dce6e5"/><path d="M24 23Q9 20 17 4l12 16m27 3Q71 20 63 4L51 20" fill="#ab9b7c" stroke="#d2c5a9" stroke-width="1.5"/><path d="m23 34-11-5 8 15m37-10 11-5-8 15" fill="#e9c2ad"/><path d="M23 28q0-15 17-15t17 15v16q-1 17-17 17T23 44Z" fill="#f0cfbd"/><path d="M20 31V24Q24 7 41 10q21 1 20 23L48 23l-9 10 1-13-11 15 1-10Z" fill="#f3f5f0"/><path d="m28 38 8-2m8 0 8 2" fill="none" stroke="#466f69" stroke-width="2"/><circle cx="33" cy="39" r="2" fill="#72ae9d"/><circle cx="47" cy="39" r="2" fill="#72ae9d"/><path d="M35 49q5 4 10 0" fill="none" stroke="#af7f71" stroke-width="1.6"/><path d="m32 61 8 9 8-9" fill="#f0cfbd"/><path d="m40 70 5 6-5 6-5-6Z" fill="#a3c9b4"/>`:`<path d="M15 85V72q0-17 25-17t25 17v13" fill="${color}"/><path d="m31 58 9 11 9-11" fill="#e5c8a7"/><path d="M22 28q0-20 18-20t18 20v14q-1 18-18 18T22 42Z" fill="${look%2?'#d0a484':'#e4b996'}"/><path d="M21 31V23Q22 5 40 7q20-2 20 21v8l-7-8-3-11q-13 10-29 14" fill="${['#5a4b3f','#333e49','#5f4b5d','#35483e','#755e48'][look%5]}"/>${look===2?'<path d="M21 29v36l-9 5V29m46-4v42l9 4V30" fill="#5f4b5d"/>':''}<circle cx="32" cy="36" r="1.6" fill="#29343a"/><circle cx="48" cy="36" r="1.6" fill="#29343a"/><path d="M35 47q5 4 10 0" fill="none" stroke="#a46e5b" stroke-width="1.7"/>${look===1||look===3?'<path d="M25 31h12v10H25Zm18 0h12v10H43Zm-6 4h6" fill="none" stroke="#35454d" stroke-width="2"/>':''}${look===4?'<path d="m54 26 7 2v17l-10 5" fill="none" stroke="#486765" stroke-width="3"/>':''}`}</svg>`;}
  function abilities(m){return `<div class="ability-list" aria-label="${esc(m.name)}的五项能力">${G.SKILLS.map(j=>{const n=m.skills[j.id];return `<div class="ability-row ${n===0?'cannot':''}"><span>${j.short}</span><div class="ability-bar" style="--ability-color:${j.color}"><i style="width:${n/2}%"></i></div><b>${n}%</b><small>${G.skillLabel(n)}</small></div>`;}).join('')}</div>`;}
  function summary(m){const strong=G.SKILLS.filter(j=>m.skills[j.id]>=130).map(j=>j.short),cannot=G.SKILLS.filter(j=>m.skills[j.id]===0).map(j=>j.short);return `${strong.length===5?'五项全能':strong.length?'擅长 '+strong.join(' / '):'多岗协作'}${cannot.length?' · 不会 '+cannot.join(' / '):''}`;}
  function workOption(s,m,j){
    const managed=G.publisherManaged(s,j.id),skill=G.taskSkill(m,j.id),cap=G.softCap(s,j.id),completion=G.progress(s,j.id),estimate=skill&&!managed?G.assignmentEstimate(s,m.id,j.id):null;
    const signed=n=>(Math.abs(n)<.05?'0':(n>0?'+':'−')+Math.abs(n).toFixed(1))+'%';
    const atCap=j.group!=='release'&&completion>=cap-1e-9;
    const predicted=managed?'发行商托管':estimate?'预计 '+signed(estimate.percent):skill?'暂不预估':'不会';
    const ceiling=j.group==='release'?'无软上限':'软上限 '+Math.round(cap*100)+'%';
    const text=(managed?'发行商托管 · ':'')+(j.id==='acquisition'&&s.adBudget===0?'⚠ 无预算 · ':'')+(atCap?(cap<1?'⚠ 已到软上限 · ':'⚠ 已完成 · '):'')+j.name+' · 完成 '+(completion*100).toFixed(1)+'% / '+ceiling+' · '+predicted+' · 能力 '+skill+'%';
    return `<option value="${j.id}"${m.job===j.id?' selected':''}${skill===0||managed?' disabled':''}>${text}</option>`;
  }
  function assignment(s,m,active){return `<label class="person-assignment"><span>本周负责</span><select data-member="${m.id}" aria-label="${esc(m.name)}本周岗位"${disabled(active)}><option value="idle"${m.job==='idle'?' selected':''}>待命（仍计工资）</option>${G.GROUPS.map(g=>`<optgroup label="${g.name}">${G.JOBS.filter(j=>j.group===g.id).map(j=>workOption(s,m,j)).join('')}</optgroup>`).join('')}</select></label>`;}

  function productionEstimate(s,m,plan){
    if(m.job==='idle')return '<span class="state-chip">待命 · 产能 0 · 仍计工资</span>';
    const warning=G.softCapWarnings(s).find(w=>w.job===m.job),base='基础产能 '+G.memberOutput(s,m.id).toFixed(1)+' 点';
    const noBudget=m.job==='acquisition'&&s.adBudget===0,alerts=[];
    if(noBudget)alerts.push('预算 ¥0 · 本周买量无进度');
    if(warning)alerts.push((warning.full?'完成度已满':'已到软上限 '+warning.cap+'%')+(warning.ongoing?' · '+warning.ongoing:''));
    const alertHtml=alerts.map(t=>'<span class="work-cap-warning">⚠ '+t+'</span>').join('');
    if(!plan)return '<div class="production-pair"><small>'+base+'</small><span>'+(s.over?'项目已结束':s.paused?'项目已暂停':'处理事件后更新预估')+'</span></div>'+alertHtml;
    const signed=n=>(Math.abs(n)<.05?'0':(n>0?'+':'−')+Math.abs(n).toFixed(1))+'%';
    const range=plan.ranges[m.job],low=range.low/s.req[m.job]*100,high=range.high/s.req[m.job]*100,amount=Math.abs(high-low)<.01?signed(high):signed(low)+' ～ '+signed(high);
    const limit=G.workLimit(s,m.job),ceiling=s.req[m.job]*G.softCap(s,m.job),notes=[];
    if(limit<ceiling-.01)notes.push(m.job==='review'?'等待资料准备完成':'受上游完成度限制');
    if(s.work[m.job]>=ceiling-.01)notes.push(G.softCap(s,m.job)<1?'已到软上限':'完成度已满');
    else if(ceiling-s.work[m.job]<plan.production[m.job])notes.push(G.softCap(s,m.job)<1?'受软上限限制':'接近 100%');
    const conditions=notes.slice();
    if(s.hard)notes.push('满效率预估，不含真实模式减速、返工与牵连');
    if(m.job!==m.lastJob)notes.push('转岗磨合 −'+Math.round(20*G.mods(s).ramp)+'%');
    const dependency=G.workDependency(s,m.job);if(dependency)notes.push('上游依赖：'+dependency.sources.map(source=>source.name+' '+(source.value*100).toFixed(1)+'%').join(' / ')+'；上游允许上限 '+(dependency.cap*100).toFixed(1)+'%');
    if(noBudget)notes.push('买量预算为 ¥0，不扣投放费，不产生买量进度；团队工资照付。');
    const shared=s.team.filter(p=>p.job===m.job).length>1?'同岗合计':'';
    return `<div class="production-pair"><div class="production-estimate" aria-label="本周岗位预计 ${amount}"><small>${s.hard?'满效率岗位预计':'本周岗位预计'}</small><b>${amount}</b></div><div class="production-base"><small>${base}</small>${shared?'<span class="state-chip">'+shared+'</span>':''}${s.hard?'<span class="state-chip">满效率</span>':''}</div></div>${alertHtml}${conditions.length?'<div class="production-conditions">'+conditions.map(t=>'<span class="state-chip">'+t+'</span>').join('')+'</div>':''}<details class="production-breakdown"><summary>产出依据</summary><ul class="production-note">${(notes.length?notes:['已计依赖与上限']).map(t=>'<li>'+t+'</li>').join('')}</ul></details>`;
  }

  function memberCard(s,m,active,candidate=false,plan=G.progressEstimate(s)){const kind=candidate?'伙伴来信':m.kind==='hero'?'主角':m.kind==='companion'?'初始搭档':'团队伙伴';return `<article class="person-card ${m.id==='ace'?'person-ai':''}" data-person="${m.id}" style="--person-color:${m.color}"><div class="person-head">${portrait(m)}<div><span class="person-kind">${kind}</span><h3>${esc(m.name)}</h3><p>${esc(m.title)}</p></div></div><p class="person-bio">${esc(m.bio)}</p>${abilities(m)}<blockquote>“${esc(m.quote)}”</blockquote><div class="person-salary">基础周薪 <b>¥${m.salary}</b>${candidate?'<span>入组准备 ¥180</span>':`<div class="person-production">${productionEstimate(s,m,plan)}</div>`}</div>${candidate?`<button class="btn-teal person-join" data-action="hire" data-id="${m.id}"${disabled(active&&!s.managed&&s.money>=180&&G.teamSize(s)<8)}>邀请${esc(m.name)}入组 · ¥180</button>`:assignment(s,m,active)}${!candidate&&m.kind==='partner'?`<button class="person-dismiss" data-action="dismiss" data-id="${m.id}"${disabled(active&&!s.managed&&s.money>=100)}>与${esc(m.name)}暂别 · ¥100</button>`:''}</article>`;}
  function autoAssignmentControls(active){return '<div class="crew-actions"><button type="button" class="btn-small btn-teal" data-action="auto-assign"'+disabled(active)+'>自动分配</button></div>';}
  function autoAssignmentHelp(){return '<details class="auto-assignment-help"><summary>自动分配怎么算？</summary><p>以本周 13 项工作平均完成度的预估增量最大为目标，计入人物能力、转岗磨合、同岗协作、软上限、刚性上限和上游依赖。遵守现有买量预算与可支付资金，排除不会的工作和发行商托管岗位；同收益优先保留现有分工。真实模式同样使用满效率预估。完成度之外的偿债与未来周收益可结合策略手动安排。</p></details>';}
  function strip(s,active,plan=G.progressEstimate(s)){return `<section class="crew-section"><div class="section-heading"><div><h2>一起做游戏的人</h2><small>能力决定产能 · 每人每周专注一岗</small></div><div class="crew-actions">${autoAssignmentControls(active)}<button class="btn-small btn-ghost" data-action="tab" data-tab="team">查看人物卡 ↗</button></div></div><p class="crew-legend">选项：当前完成度 / 软上限 · 选岗后团队合计预估 · 人物能力。预估按满效率计算，计入上游依赖、上限、转岗磨合与同岗协作。</p>${autoAssignmentHelp()}<div class="crew-strip">${s.team.map(m=>`<article class="crew-mini" style="--person-color:${m.color}"><div class="crew-mini-head">${portrait(m)}<div><strong>${esc(m.name)} <small>${m.kind==='hero'?'主角':m.id==='ace'?'龙娘搭档':''}</small></strong><p>${summary(m)}</p></div></div>${assignment(s,m,active)}<div class="contribution">${productionEstimate(s,m,plan)}</div></article>`).join('')}</div></section>`;}
  function roster(s,active,plan=G.progressEstimate(s)){const candidates=G.availableRecruits(s);return `<div class="section-heading"><h2>本周团队分工</h2>${autoAssignmentControls(active)}</div>${autoAssignmentHelp()}<p class="legend">100% 为标准能力；擅长 ≥130%，不会的岗位不能分配。天才程序员每项 145%，每周仍只负责一岗。同岗最有效成员发挥全产能，其余按协作效率折算；转岗磨合按每个人上周的实际岗位计算。</p><p class="crew-legend">岗位预估为选岗后的团队合计，按满效率、依赖与上限计算；详细依据可展开查看。</p><div class="people-grid">${s.team.map(m=>memberCard(s,m,active,false,plan)).join('')}</div><div class="section-heading"><div><h2>伙伴来信 <span class="pill gold">${candidates.length}</span></h2><small>随作品进展结识新伙伴，按团队缺口决定是否邀请</small></div></div>${candidates.length?`<div class="people-grid">${candidates.map(m=>memberCard(s,m,active,true,plan)).join('')}</div>`:'<section class="panel people-empty"><h3>下一个愿意与你同行的人，正在路上。</h3><p>可玩原型（核心平均 30%）：林绘 / 沈序<br>垂直切片（65%）：唐砚 / 温衡<br>内容完成：夏禾 / 陆简</p></section>'}<p class="legend" style="margin-top:18px">邀请和暂别占用本周管理行动；邀请不推进时间，新伙伴首周需要磨合。整个团队会带入下一关；主角与天才程序员始终留队。伙伴暂别后本项目不能再次邀请，但结识关系跨关保留。</p>`;}
  function voice(s,event){const v=G.teamVoice(s,event),m=s.team.find(m=>m.id===v.id);return `<div class="team-voice">${portrait(m)}<div><strong>${esc(v.name)}</strong><p>${esc(v.text)}</p></div></div>`;}
  window.StudioPeople={portrait,abilities,summary,assignment,productionEstimate,memberCard,strip,roster,voice};
})();
